      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "NY0128, a guanidine-containing compound, crosses the BBB, but its structure is dominated by a bulky triphenylmethyl ether that provides lipophilicity absent in the query; therefore it does not establish meaningful access for the dicationic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Pitolisant shows high brain penetration (brain-to-plasma ratio ~3.9), but it is a lipophilic basic amine without the dicationic guanidine-azocane core, so its transfer to the query is limited.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "Tremorine crosses the BBB and produces central effects, but it is a lipophilic bis-pyrrolidine alkyne, not a dicationic guanidine; this does not outweigh the query's ionization liability.",
      "evidence_role": "contradictory"
    }
  ],
